/**
 * Briefing generator for the autonomous reviewer executor.
 *
 * Produces a markdown briefing that instructs the executor to run /review-pr,
 * exactly as the implementation briefing instructs /start-implementation.
 *
 * The reviewer reads the PR diff + task spec + technical design, evaluates the
 * rubric in technical_skills/review-pr/references/review_criteria.md, posts a
 * GitHub APPROVE or REQUEST_CHANGES review, and writes result.json with:
 *   { terminal_status: "passed" | "change_requested" | "escalate", ... }
 */

import {
  preambleSection,
  identitySection,
  taskContextSection,
  modelSection,
  joinSections,
} from "./briefing-template.js";

export interface ReviewerBriefingOpts {
  taskId: string;
  featureId: string;
  taskTitle: string;
  taskBranch: string;
  taskRepo: string;
  taskRepoRoot: string;
  workspaceRoot: string;
  prUrl: string;
  gitAuthorEmail: string;
  gitAuthorName: string;
  reviewerModel: string;
  resultPath: string;
  /** Current count of in_review log entries — used for cycle-limit display. */
  reviewCycleCount: number;
  /** Max review cycles before escalating. Default: 3. */
  maxReviewCycles: number;
}

/**
 * Generate the per-activation briefing markdown for the reviewer executor.
 *
 * Sections (in order):
 *   1. Preamble — automated context, no interactive session
 *   2. ## Identity
 *   3. ## Your claimed task
 *   4. ## What you must do
 *   5. ## Model
 *   6. ## Rules
 */
export function generateReviewerBriefing(opts: ReviewerBriefingOpts): string {
  const {
    taskId,
    featureId,
    taskTitle,
    taskBranch,
    taskRepo,
    taskRepoRoot,
    workspaceRoot,
    prUrl,
    gitAuthorEmail,
    gitAuthorName,
    reviewerModel,
    resultPath,
    reviewCycleCount,
    maxReviewCycles,
  } = opts;

